INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'bronco', 'ground-clearance', $s$Ford$s$, $s$Bronco$s$, $s$Ground clearance$s$, $s$Ford Bronco Ground Clearance, Angles and Water Fording by Tire Size$s$, $s$Ford Bronco Ground Clearance by Trim and Tire Size$s$, $s$Ford Bronco ground clearance from Ford's 2026 spec sheet: 8.3 in on 30 in tires up to 13.1 in on the Raptor, with angles and water fording depth.$s$, $s$[{"q": "What is the ground clearance of a Ford Bronco?", "a": "From 8.3 in to 13.1 in for 2026, depending on the tires the truck was built with. A Base on 30 in tires has 8.3 to 8.4 in; the Raptor on 37 in tires has 13.1 in."}, {"q": "How much clearance does the Sasquatch Package give?", "a": "11.6 in on the 2-door and 11.5 in on the 4-door, on 35 in tires, by Ford's sheet."}, {"q": "How deep can a Bronco ford water?", "a": "Ford lists a maximum of 31.5 in for the 30, 32 and 33 in tire builds, 33.5 in with the Sasquatch Package and 37.0 in for the Raptor. Ford adds: always determine the depth before crossing and proceed slowly."}, {"q": "Does the 2-door have better angles than the 4-door?", "a": "The breakover angle is better on the shorter 2-door: 28.9 degrees against 26.3 with the Sasquatch Package. Approach angles are the same."}]$s$::jsonb, $s${"answer": "A 2026 Ford Bronco has between 8.3 and 13.1 in of ground clearance, set mostly by its tires: 8.3 to 8.4 in on the Base, 9.4 in on Big Bend and Outer Banks, 10.5 in on the Badlands, 11.5 to 11.6 in with the Sasquatch Package and 13.1 in on the Raptor.", "reviewed": "2026-11-19", "covers": "Model year 2026", "not_covered": "2021 to 2025: Ford's sheets for these years are not on this page yet. Ford's sheet lists no figures for the 2-door on 32 in tires.", "sections": [{"id": "clearance", "h": "Ground clearance, angles and fording depth (2026)", "intro": "Angles are in degrees.", "table": {"head": ["Trim or package", "Tire", "Body", "Ground clearance", "Approach", "Departure", "Breakover", "Max water fording"], "rows": [["Base", "30 in", "2-door", "8.3 in", "35.7", "29.9", "21.3", "31.5 in", 1], ["Base", "30 in", "4-door", "8.4 in", "35.7", "29.8", "19.6", "31.5 in", 1], ["Big Bend, Outer Banks", "32 in", "4-door", "9.4 in", "38.3", "32.1", "22.1", "31.5 in", 1], ["Badlands", "33 in", "2-door", "10.5 in", "41.3", "34.6", "26.4", "31.5 in", 1], ["Badlands", "33 in", "4-door", "10.5 in", "41.3", "34.5", "24.1", "31.5 in", 1], ["Sasquatch Package", "35 in", "2-door", "11.6 in", "43.3", "37.0", "28.9", "33.5 in", 1], ["Sasquatch Package", "35 in", "4-door", "11.5 in", "43.3", "36.9", "26.3", "33.5 in", 1], ["Raptor", "37 in", "4-door", "13.1 in", "47.2", "40.5", "30.8", "37.0 in", 1]]}}], "check": ["Check the tire size on the sidewall: the figures follow the tire the truck left the factory with.", "A lift kit or larger tires change every number in the table, and steps or a hitch can reduce the breakover and departure angles.", "Before a water crossing, read the fording section of the owner's manual.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "led-light-bars"], "sources": [["Ford, 2026 Bronco Technical Specifications (v1.0, 18 Feb 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Bronco_Technical_Specifications.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-19', TIMESTAMPTZ '2026-11-19 10:00:00+06', 'model', '')
