INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'expedition', 'cargo-space', $s$Ford$s$, $s$Expedition$s$, $s$Cargo space$s$, $s$Ford Expedition Cargo Space: Expedition vs Expedition MAX$s$, $s$Ford Expedition Cargo Space vs Expedition MAX (cu ft)$s$, $s$Ford Expedition cargo space from Ford's 2026 spec sheet: 21.6 cu ft behind the third row, 36.1 cu ft in the MAX, up to 108.5 and 123.1 cu ft.$s$, $s$[{"q": "How much cargo space does a Ford Expedition have?", "a": "21.6 cu ft behind the third row, 60.8 cu ft behind the second and 108.5 cu ft behind the first, by Ford's 2026 sheet."}, {"q": "How much more does the Expedition MAX hold?", "a": "36.1 cu ft behind the third row, 75.4 cu ft behind the second and 123.1 cu ft behind the first: about 14.5 cu ft more at each position."}, {"q": "How much longer is the Expedition MAX?", "a": "221.7 in against 209.9 in, on a 131.5 in wheelbase instead of 122.5 in."}, {"q": "How big is the fuel tank?", "a": "23.6 gallons in the Expedition and 27.8 gallons in the Expedition MAX."}]$s$::jsonb, $s${"answer": "The 2026 Ford Expedition has 21.6 cu ft of cargo space behind the third row, 60.8 cu ft behind the second and 108.5 cu ft behind the first. The Expedition MAX has 36.1, 75.4 and 123.1 cu ft.", "reviewed": "2026-11-19", "covers": "Model year 2026", "not_covered": "Earlier model years are not on this page yet.", "sections": [{"id": "cargo", "h": "Cargo area volume (2026)", "table": {"head": ["Measurement", "Expedition", "Expedition MAX"], "rows": [["Behind the third row", "21.6 cu ft", "36.1 cu ft", 1], ["Behind the second row", "60.8 cu ft", "75.4 cu ft", 1], ["Behind the first row", "108.5 cu ft", "123.1 cu ft", 1]]}, "notes": ["The figures are the same for 4x2 and 4x4."]}, {"id": "size", "h": "Size, ground clearance and fuel tank (2026)", "table": {"head": ["Measurement", "Expedition 4x4", "Expedition MAX 4x4", "Expedition Tremor"], "rows": [["Overall length", "209.9 in", "221.7 in", "209.9 in", 1], ["Wheelbase", "122.5 in", "131.5 in", "122.4 in", 1], ["Width, mirrors folded", "84.6 in", "84.6 in", "84.6 in", 1], ["Maximum height", "78.0 in", "77.9 in", "78.9 in", 1], ["Ground clearance", "8.7 in", "8.7 in", "10.6 in", 1]]}, "notes": ["Fuel capacity is 23.6 gallons for the Expedition and 27.8 gallons for the Expedition MAX."]}], "check": ["Measure your garage against the length and the width with the mirrors folded before choosing the MAX.", "Adding a roof box or rack: add its height to the maximum height row.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["cargo-boxes", "roof-racks", "floor-mats"], "sources": [["Ford, 2026 Expedition Technical Specifications (v1.0, 5 Feb 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Expedition_Technical_Specfications.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-21', TIMESTAMPTZ '2026-11-21 10:00:00+06', 'model', '')
