INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'f-150', 'payload-capacity', $s$Ford$s$, $s$F-150$s$, $s$Payload capacity$s$, $s$Ford F-150 Payload Capacity by Engine (2026)$s$, $s$Ford F-150 Payload Capacity by Engine (2026)$s$, $s$Ford F-150 payload capacity from Ford's 2026 spec sheet: up to 2,440 lb with the 3.5L EcoBoost, 1,405 to 2,235 lb with the other engines.$s$, $s$[{"q": "What is the maximum payload of a 2026 F-150?", "a": "2,440 lb, with the 3.5L EcoBoost V6 and 4x2, according to Ford's specification sheet."}, {"q": "What is the payload of an F-150 hybrid?", "a": "Up to 2,045 lb with 4x2 and 1,740 lb with 4x4 for the 3.5L PowerBoost."}, {"q": "What is the payload of a Raptor?", "a": "Ford lists 1,405 lb for the 3.5L EcoBoost High Output and 1,410 lb for the 5.2L supercharged V8, the second with the 37 in tires."}, {"q": "Where do I find the payload of my own truck?", "a": "On the yellow tire and loading label on the driver's door jamb. It is specific to your truck and is usually lower than the maximum on this page."}]$s$::jsonb, $s${"answer": "The 2026 Ford F-150 carries up to 2,440 lb of payload with the 3.5L EcoBoost V6. The other engines top out between 1,405 and 2,235 lb. These are maximum figures by engine; the payload of an individual truck is printed on its door-jamb label.", "reviewed": "2026-11-19", "covers": "Model year 2026", "not_covered": "Earlier model years, and the breakdown by cab, box and package: Ford's sheet gives the maximum per engine only.", "sections": [{"id": "payload", "h": "Maximum payload by engine (2026)", "table": {"head": ["Engine", "4x2", "4x4"], "rows": [["2.7L EcoBoost V6", "1,775 lb", "1,715 lb", 1], ["5.0L V8", "2,235 lb", "2,080 lb", 1], ["3.5L EcoBoost V6", "2,440 lb", "2,175 lb", 1], ["3.5L PowerBoost Full Hybrid V6", "2,045 lb", "1,740 lb", 1], ["3.5L EcoBoost V6 High Output", "—", "1,405 lb", 1], ["5.2L supercharged V8 (37 in tires)", "—", "1,410 lb", 1]]}, "notes": ["Ford's note: maximum payload varies with accessories and vehicle configuration; see the door-jamb label for the carrying capacity of a specific vehicle.", "Payload counts everything you add to the truck: people, cargo, a bed cover or rack, and the tongue weight of a trailer."]}], "check": ["Read the yellow tire and loading label on the driver's door jamb. It gives the most that occupants and cargo together may weigh on your truck.", "Subtract the weight of accessories you have added, such as a hard tonneau cover, a bed rack or steps.", "Towing: subtract the trailer's tongue weight too.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["bed-racks", "tonneau-covers", "hitches"], "sources": [["Ford, 2026 F-150 Technical Specifications (v1.1, 31 Mar 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_F150_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-19', TIMESTAMPTZ '2026-11-19 10:00:00+06', 'model', '')
