INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'maverick', 'ground-clearance', $s$Ford$s$, $s$Maverick$s$, $s$Ground clearance$s$, $s$Ford Maverick Ground Clearance and Off-Road Angles by Trim$s$, $s$Ford Maverick Ground Clearance by Trim (Inches)$s$, $s$Ford Maverick ground clearance from Ford's 2026 spec sheet: 8.0 to 8.3 in on most trucks, 9.1 in on the Tremor, 7.4 in on the Lobo, plus angles.$s$, $s$[{"q": "What is the ground clearance of a Ford Maverick?", "a": "Between 7.4 and 9.1 in for 2026, by Ford's specification sheet: 8.0 to 8.3 in on the Hybrid and EcoBoost trucks, 9.1 in on the Tremor and 7.4 in on the Lobo."}, {"q": "Which Maverick sits highest?", "a": "The Tremor, at 9.1 in of minimum running ground clearance and a 30.8 degree approach angle."}, {"q": "Why is the Lobo lower?", "a": "Ford lists the Lobo at 7.4 in, the lowest of the lineup. It is the street-oriented version of the truck."}, {"q": "Does a lift or leveling kit change these figures?", "a": "Yes. The table is for the truck as Ford builds it. Different tires or suspension parts change the clearance and the angles."}]$s$::jsonb, $s${"answer": "The 2026 Ford Maverick has 8.0 to 8.3 in of minimum running ground clearance in Hybrid and EcoBoost form, 9.1 in as a Tremor and 7.4 in as a Lobo, according to Ford's specification sheet.", "reviewed": "2026-11-19", "covers": "Model year 2026", "not_covered": "2022 to 2025: Ford's sheets for these years are not on this page yet.", "sections": [{"id": "clearance", "h": "Ground clearance and angles (2026)", "intro": "Ford calls the figure minimum running ground clearance. Angles are in degrees.", "table": {"head": ["Powertrain or trim", "Ground clearance", "Approach", "Departure", "Breakover"], "rows": [["2.5L Hybrid, FWD", "8.1 in", "20.3", "22.2", "16.7", 1], ["2.5L Hybrid, AWD", "8.1 in", "20.4", "21.0", "15.9", 1], ["2.0L EcoBoost, FWD", "8.0 in", "20.1", "22.4", "18.1", 1], ["2.0L EcoBoost, AWD", "8.3 in", "21.1", "21.1", "18.3", 1], ["Tremor (AWD)", "9.1 in", "30.8", "21.6", "20.1", 1], ["Lobo (AWD)", "7.4 in", "19.0", "19.3", "17.0", 1]]}}, {"id": "size", "h": "Height and length (2026)", "table": {"head": ["Powertrain or trim", "Maximum height", "Length"], "rows": [["2.5L Hybrid, FWD", "68.8 in", "199.8 in", 1], ["2.5L Hybrid, AWD", "68.3 in", "199.8 in", 1], ["2.0L EcoBoost, FWD", "68.9 in", "199.8 in", 1], ["2.0L EcoBoost, AWD", "68.5 in", "199.8 in", 1], ["Tremor (AWD)", "69.4 in", "200.6 in", 1], ["Lobo (AWD)", "67.7 in", "200.9 in", 1]]}}], "check": ["Measure from level ground to the lowest fixed point under the truck, unloaded. A loaded bed lowers the rear.", "Shopping for a lift or leveling kit: compare the kit's stated lift with the figure for your trim, not with another trim.", "Garage or car wash height: use the maximum height row, and add the height of any rack.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "roof-racks"], "sources": [["Ford, 2026 Maverick Technical Specifications (v1.2, 20 Jul 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Maverick_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-19', TIMESTAMPTZ '2026-11-19 10:00:00+06', 'model', '')
