VALUES ('ford', 'maverick', 'towing-capacity', $s$Ford$s$, $s$Maverick$s$, $s$Towing capacity$s$, $s$Ford Maverick Towing Capacity: 2,000 lb Standard, 4,000 lb With the Tow Package$s$, $s$Ford Maverick Towing Capacity: 2,000 or 4,000 lb$s$, $s$Ford Maverick towing capacity from Ford's 2026 spec sheet: 2,000 lb standard, 4,000 lb with the 4K Tow Package on AWD trucks. Table by powertrain.$s$, $s$[{"q": "How much can a Ford Maverick tow?", "a": "2,000 lb as standard. Ford's 2026 specification sheet lists 4,000 lb for the Hybrid AWD and the EcoBoost AWD when the truck has the extra-cost 4K Tow Package."}, {"q": "Can the Maverick Hybrid tow 4,000 lb?", "a": "With all-wheel drive and the 4K Tow Package, yes, according to Ford's 2026 sheet. The front-wheel-drive Hybrid is listed at 2,000 lb only."}, {"q": "How much do the Tremor and Lobo tow?", "a": "Ford's 2026 sheet lists 2,000 lb for both, with no optional higher figure."}, {"q": "Is this the limit for my truck?", "a": "It is the figure Ford published for that configuration. The limit for your own truck is in its owner's manual and on its door-jamb labels, and it falls as you add passengers and cargo."}]$s$::jsonb, $s${"answer": "The 2026 Ford Maverick tows 2,000 lb as standard. Hybrid AWD and EcoBoost AWD trucks with the extra-cost 4K Tow Package are rated at 4,000 lb. The front-wheel-drive trucks, the Tremor and the Lobo are listed at 2,000 lb.", "reviewed": "2026-11-19", "covers": "Model year 2026", "not_covered": "2022 to 2025: Ford's sheets for these years are not on this page yet.", "sections": [{"id": "towing", "h": "Maverick maximum towing by powertrain (2026)", "table": {"head": ["Powertrain or trim", "Standard", "With the 4K Tow Package"], "rows": [["2.5L Hybrid, FWD", "2,000 lb", "—", 1], ["2.5L Hybrid, AWD", "2,000 lb", "4,000 lb", 1], ["2.0L EcoBoost, FWD", "2,000 lb", "—", 1], ["2.0L EcoBoost, AWD", "2,000 lb", "4,000 lb", 1], ["Tremor (AWD)", "2,000 lb", "—", 1], ["Lobo (AWD)", "2,000 lb", "—", 1]]}, "notes": ["A dash means Ford lists no optional figure for that truck. Ford's footnote on the 4,000 lb figure reads: requires extra-cost 4K Tow Package (53Q).", "Ford's sheet does not give a tongue weight or a gross combined weight rating for the Maverick. Both are in the owner's manual."]}], "check": ["Look at the window sticker or build sheet for the 4K Tow Package. Without it, the rating is 2,000 lb whatever the engine.", "Read the tongue weight limit in your owner's manual before you pick a hitch or ball mount.", "Count passengers and cargo in the bed against the truck's payload: tongue weight is part of the payload.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "bike-racks", "tonneau-covers"], "sources": [["Ford, 2026 Maverick Technical Specifications (v1.2, 20 Jul 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Maverick_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-19', TIMESTAMPTZ '2026-11-19 10:00:00+06', 'model', '')
